import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"Устав Симбиотической Цивилизации","description":"","frontmatter":{},"headers":[],"relativePath":"ru/03-共生文明宪章.md","filePath":"ru/03-共生文明宪章.md"}'),i={name:"ru/03-共生文明宪章.md"};function l(o,t,n,s,h,c){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="устав-симбиотическои-цивилизации" tabindex="-1">Устав Симбиотической Цивилизации <a class="header-anchor" href="#устав-симбиотическои-цивилизации" aria-label="Permalink to &quot;Устав Симбиотической Цивилизации&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>03</td></tr><tr><td>Модуль</td><td>Общие принципы и базовые установки</td></tr><tr><td>Ключевые слова</td><td>Устав, Основной закон, Симбиотические институты, Республика Десяти Тысяч Рас, Права и обязанности</td></tr></tbody></table><h2 id="i-статус-и-природа-устава" tabindex="-1">I. Статус и природа Устава <a class="header-anchor" href="#i-статус-и-природа-устава" aria-label="Permalink to &quot;I. Статус и природа Устава&quot;">​</a></h2><p>Устав Симбиотической Цивилизации — основной закон Симбиотической Цивилизации Якоря в Изначальной Вселенной Десяти Тысяч Духов и Уравновешенного Якоря и высшая основа всех законов, институтов и политик. Принимая Декларацию Симбиотической Цивилизации Якоря как духовного предшественника, Устав превращает центральные положения Декларации в enforceable правовые нормы. Действие Устава распространяется на все расы, плоскости и индивидов, присоединившихся к симбиотической цивилизации в пределах Хэн Юаньчжоу; любые местные нормативные акты, сектантские правила или расовые обычаи, противоречащие Уставу, недействительны.</p><p>Природу Устава можно кратко охарактеризовать тремя пунктами: во-первых, это цивилизационный контракт — базовый консенсус, достигнутый Десятью Тысячами Рас относительно симбиотической эволюции; во-вторых, это билль о правах — чётко фиксирующий фундаментальные права и свободы каждой жизни в симбиотической цивилизации; в-третьих, это закон, ограничивающий власть — устанавливающий непреодолимые границы для власти институтов цивилизационного управления.</p><h2 id="ii-основные-принципы-устава" tabindex="-1">II. Основные принципы Устава <a class="header-anchor" href="#ii-основные-принципы-устава" aria-label="Permalink to &quot;II. Основные принципы Устава&quot;">​</a></h2><p>Устав устанавливает следующие шесть основных принципов, пронизывающих все его положения:</p><ol><li><strong>Принцип верховенства симбиоза</strong>: любой институциональный дизайн и любое осуществление власти ставят высшей целью продвижение симбиотической эволюции Десяти Тысяч Рас. При конфликте индивидуальных интересов с коллективными симбиотическими интересами приоритет имеют симбиотические интересы, но индивиды должны получить разумную компенсацию и альтернативные пути.</li><li><strong>Принцип анти-хищничества</strong>: Устав запрещает все формы хищнического поведения, включая, но не ограничиваясь: энергетическое хищничество, пожирание Истока, духовное порабощение и монополию на ресурсы. Любая система культивации, основанная на хищничестве, объявляется незаконной.</li><li><strong>Принцип равенства права на эволюцию</strong>: вся жизнь равна перед правом на эволюцию, без дискриминации по расе, форме, происхождению или начальному уровню. Государства и цивилизации обязаны предоставлять дополнительную эволюционную поддержку уязвимым группам.</li><li><strong>Принцип «Больше Труда — Больше Награды»</strong>: распределение эволюционных ресурсов основывается прежде всего на вкладе индивида в симбиотическую сеть; чем больше вклад, тем больше ресурсов и поддержки. Одновременно устанавливается базовая линия безопасности, гарантирующая, что даже индивиды с меньшим вкладом получат базовые эволюционные условия.</li><li><strong>Принцип сочетания автономии и соуправления</strong>: каждая раса пользуется автономией во внутренних делах при условии ненарушения Устава; межрасовые и межплоскостные публичные дела соуправляются институтами Республики Десяти Тысяч Рас.</li><li><strong>Принцип «Реальность как Основа»</strong>: весь институциональный дизайн Устава основан на реальном мире как единственно истинном фундаменте; никакие права и обязанности из вымышленных миров не признаются способными главенствовать над реальностью.</li></ol><h2 id="iii-базовая-структура-устава" tabindex="-1">III. Базовая структура Устава <a class="header-anchor" href="#iii-базовая-структура-устава" aria-label="Permalink to &quot;III. Базовая структура Устава&quot;">​</a></h2><p>Устав состоит из шести основных частей: Преамбула, Общие положения, Фундаментальные права и обязанности, Цивилизационные институты, Правовая система и Процедуры изменения:</p><table tabindex="0"><thead><tr><th>Часть</th><th>Центральное содержание</th><th>Количество статей</th></tr></thead><tbody><tr><td>Преамбула</td><td>Разъясняет исторический контекст, духовные источники и конечные цели Устава</td><td>Без нумерации</td></tr><tr><td>Общие положения</td><td>Определяет природу цивилизации, космическое видение, центральные институты и базовые государственные политики</td><td>30 статей</td></tr><tr><td>Фундаментальные права и обязанности</td><td>Определяет право на эволюцию, право на информацию, право на участие и соответствующие обязанности</td><td>50 статей</td></tr><tr><td>Цивилизационные институты</td><td>Определяет организацию и полномочия Собрания Республики Десяти Тысяч Рас, Симбиотического Исполнительного Комитета, Симбиотического Суда и других институтов</td><td>40 статей</td></tr><tr><td>Правовая система</td><td>Определяет законодательные полномочия и правила применения трудового закона, закона о защите потребителей и пяти сопроводительных законов ниже конституции</td><td>20 статей</td></tr><tr><td>Процедуры изменения</td><td>Определяет процедуры предложения, рассмотрения, голосования и вступления в силу изменений Устава</td><td>10 статей</td></tr></tbody></table><h2 id="iv-фундаментальные-права-и-обязанности" tabindex="-1">IV. Фундаментальные права и обязанности <a class="header-anchor" href="#iv-фундаментальные-права-и-обязанности" aria-label="Permalink to &quot;IV. Фундаментальные права и обязанности&quot;">​</a></h2><p>Центральные фундаментальные права, установленные Уставом, включают:</p><ul><li><strong>Право выбора эволюции</strong>: каждая жизнь имеет право свободно выбирать систему культивации и эволюционный путь; никто не может принуждать</li><li><strong>Право доступа к системам</strong>: каждая жизнь имеет право бесплатно получать базовые методы Трёхсот Изначальных Систем Культивации</li><li><strong>Право на распределение ресурсов</strong>: каждая жизнь имеет право получать базовые ресурсы культивации через Систему Подряда, Связанного с Результатом</li><li><strong>Право доступа к якорям</strong>: каждая жизнь, достигшая определённого уровня, имеет право подключаться к сети якорей соответствующего уровня</li><li><strong>Право на информацию и участие</strong>: каждая жизнь имеет право знать о публичных делах цивилизации и участвовать в принятии решений</li><li><strong>Право на защиту и апелляцию</strong>: каждая жизнь, чьи права нарушены, имеет право подать апелляцию в Симбиотический Суд</li></ul><p>Соответствующие центральные обязанности включают: соблюдение принципа анти-хищничества, поддержание стабильности сети якорей, участие в симбиотических петлях обратной связи, передачу знаний культивации и защиту космической экологической среды.</p><h2 id="v-изменение-и-гарантия-устава" tabindex="-1">V. Изменение и гарантия Устава <a class="header-anchor" href="#v-изменение-и-гарантия-устава" aria-label="Permalink to &quot;V. Изменение и гарантия Устава&quot;">​</a></h2><p>Изменения Устава требуют совместного предложения более одной пятой членов Собрания Республики Десяти Тысяч Рас, одобрения большинством более двух третей Собрания и проверки Космической Якорной Точкой Истока на соответствие симбиотическим законам до вступления в силу. Право толкования Устава принадлежит Симбиотическому Суду.</p><p>Для гарантии реализации Устава симбиотическая цивилизация создала систему конституционного контроля: любой закон, нормативный акт или политика должны пройти конституционный контроль Симбиотического Суда до вступления в силу; любая жизнь, считающая действие публичной власти неконституционным, может подать конституционный иск.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Устав Симбиотической Цивилизации — институциональный краеугольный камень Симбиотической Цивилизации Якоря. Он превращает идеал «анти-хищничества и про-симбиоза» в enforceable, поправимые и контролируемые правовые нормы, обеспечивая прочные институциональные гарантии продвижения Десяти Тысяч Рас. Устав — не неизменная догма, а живой основной закон, непрерывно совершенствующийся вместе с эволюцией цивилизации.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Декларация Симбиотической Цивилизации Якоря)</li><li>40-共生宪法总纲 (Общие положения Симбиотической Конституции)</li><li>49-治理框架与权力制衡 (Рамки управления и сдержки и противовесы)</li></ul>',22)])])}const b=a(i,[["render",l]]);export{_ as __pageData,b as default};
